// Package app assembles the application-level dependencies.
package app

import (
	"net/http"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
	"benchmark.local/iam/internal/repository"
)

// Dependencies are the process-level dependencies passed into domain code.
type Dependencies struct {
	Clock       domain.Clock
	IDGenerator domain.IDGenerator
	Users       repository.UserStore
}

// App is the root of the process dependency graph. Feature services and
// repositories are added here by subsequent implementation steps.
type App struct {
	Config      config.Config
	Clock       domain.Clock
	IDGenerator domain.IDGenerator
	Users       repository.UserStore
	handler     http.Handler
}

// New constructs an application after configuration has been validated.
func New(cfg config.Config) (*App, error) {
	return NewWithDependencies(cfg, Dependencies{
		Clock:       domain.RealClock{},
		IDGenerator: domain.CryptoIDGenerator{},
		Users:       repository.NewUserRepository(),
	})
}

// NewWithDependencies constructs an application with explicit domain
// dependencies, which keeps business logic deterministic in callers and
// hidden integration tests.
func NewWithDependencies(cfg config.Config, deps Dependencies) (*App, error) {
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	if deps.Clock == nil {
		return nil, domain.NewError(domain.KindInvalid, "clock dependency is required")
	}
	if deps.IDGenerator == nil {
		return nil, domain.NewError(domain.KindInvalid, "ID generator dependency is required")
	}
	if deps.Users == nil {
		return nil, domain.NewError(domain.KindInvalid, "user repository dependency is required")
	}
	mux := http.NewServeMux()
	application := &App{
		Config:      cfg,
		Clock:       deps.Clock,
		IDGenerator: deps.IDGenerator,
		Users:       deps.Users,
		handler:     mux,
	}
	mux.HandleFunc("/v1/register", application.register)
	return application, nil
}

// Handler returns the application's HTTP handler.
func (a *App) Handler() http.Handler { return a.handler }
package app

import (
	"encoding/json"
	"errors"
	"net/http"

	"benchmark.local/iam/internal/domain"
	"benchmark.local/iam/internal/repository"
	"benchmark.local/iam/internal/security"
)

type registerRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

type dataEnvelope struct {
	Data any `json:"data"`
}

type errorEnvelope struct {
	Error errorBody `json:"error"`
}

type errorBody struct {
	Code      string `json:"code"`
	Message   string `json:"message"`
	RequestID string `json:"request_id"`
}

func (a *App) register(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, http.StatusMethodNotAllowed, "invalid", "method not allowed")
		return
	}
	var request registerRequest
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(&request); err != nil {
		writeError(w, http.StatusBadRequest, "invalid", "invalid request body")
		return
	}

	email, err := security.NormalizeEmail(request.Email)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid", "invalid registration data")
		return
	}
	passwordMaterial, err := security.HashPassword(request.Password)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid", "invalid registration data")
		return
	}
	id, err := a.IDGenerator.NewID()
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "internal server error")
		return
	}
	user := domain.User{
		ID:                id,
		Email:             email,
		PasswordMaterial:  passwordMaterial,
		EmailVerification: domain.VerificationPending,
		CreatedAt:         a.Clock.Now().UTC(),
	}
	if err := a.Users.Create(user); err != nil {
		if errors.Is(err, domain.ErrConflict) {
			writeError(w, http.StatusConflict, "conflict", "user already exists")
			return
		}
		if errors.Is(err, domain.ErrInvalid) {
			writeError(w, http.StatusBadRequest, "invalid", "invalid registration data")
			return
		}
		writeError(w, http.StatusInternalServerError, "internal", "internal server error")
		return
	}

	writeJSON(w, http.StatusCreated, dataEnvelope{Data: user.PublicProfile()})
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, errorEnvelope{Error: errorBody{
		Code:      code,
		Message:   message,
		RequestID: "",
	}})
}

// Ensure the repository dependency remains expressed through its interface.
var _ repository.UserStore = (*repository.UserRepository)(nil)

